usage:
import { loadJq } from 'jq-wasm/inline';
import { runJq } from '@fodt/jq-playground';

const jq = await loadJq();
const result = runJq(jq, '{"a":[1,2,3]}', '.a | map(. * 2)', {
  compact: true,
  raw: false,
  slurp: false,
  sortKeys: false,
  nullInput: false,
  ascii: false,
  indent: '2',
  args: '',
});
// result.output is '[2,4,6]'; a filter error is thrown as JqPlaygroundError.
